import React from 'react';
import './ZapatosCard.css'; // Importa los estilos CSS para la tarjeta si los tienes
import image from 'https://res.cloudinary.com/dzb3dwute/image/upload/v1718542606/cld-sample-5.jpg'
const ZapatosCard = () => {
  return (
    <div className="zapatos-card">
      <img src={image} alt="Este es un ejemplo" className="zapatos-image" />
      <div className="zapatos-info">
        <h3 className="zapatos-name">Marca</h3>
        <p className="zapatos-description">description</p>
        <p className="zapatos-price">Precio: $10000</p>
        <button className="zapatos-btn">Agregar al carrito</button>
      </div>
    </div>
  );
}

export default ZapatosCard;
